INSERT INTO tour_translations (tour_id, lang, name, summary, description, stops, included, extras) VALUES (3, 'en', 'La Route du Thé', 'Colonial estates, tea and rum tasting, the vanilla house and the wild cliffs of Gris Gris.', 'The south of Mauritius through its tea, vanilla and rum. Departure 09:00 to 17:00, or 08:30 to 16:30, with hotel pickup and return.', '["Domaine des Aubineaux","Bois Chéri, with tea tasting","Domaine de St Aubin","Vanilla house","Lunch","Rum tasting","Gris Gris seaside"]', '["Hotel pickup and return","Lunch","Tea tasting","Rum tasting"]', '[]');
