INSERT INTO content_blocks (key, lang, value, updated_at) VALUES ('about', 'en', '{"title":"Your Gateway to Mauritian Paradise","paragraphs":["Based in the heart of Mauritius, Just Love Tour is your trusted partner for discovering the island''s hidden gems.","Our local expertise and passion for hospitality ensure every journey is personalized, safe, and absolutely unforgettable."]}', 1793145600000);
INSERT INTO content_blocks (key, lang, value, updated_at) VALUES ('about', 'fr', '{"title":"Votre Porte vers le Paradis Mauricien","paragraphs":["Basé au cœur de Maurice, Just Love Tour est votre partenaire de confiance pour découvrir les trésors cachés de l''île.","Notre expertise locale et notre passion pour l''hospitalité garantissent un voyage personnalisé, sûr et absolument inoubliable."]}', 1793145600000);
INSERT INTO content_blocks (key, lang, value, updated_at) VALUES ('about', 'ru', '{"title":"Ваш путь в райский Маврикий","paragraphs":["Работая в самом сердце Маврикия, Just Love Tour помогает открывать скрытые сокровища острова.","Наш местный опыт и любовь к гостеприимству делают каждую поездку персональной, безопасной и по-настоящему незабываемой."]}', 1793145600000);
